const scenes=['./media/coast.svg','./media/mountain.svg','./media/forest.svg'];
function assetImg(i,label,cls=''){return `<img class="${cls}" src="${scenes[i%3]}" alt="${esc(label)}" loading="lazy">`}
export function renderExtra(id,{lang='ko',variant='Default'}={}){const t=strings[lang],x=extraStrings[lang];const v=variant.toLowerCase();let h='';
 switch(id){
 case 'range-slider':h=`<strong>${t.amount}</strong><div class="jy-between jy-small"><output data-range-min-label>40,000</output><output data-range-max-label>180,000</output></div><input class="jy-range" type="range" min="0" max="300000" step="10000" value="40000" aria-label="${t.amount} min" data-extra="range-min"><input class="jy-range" type="range" min="0" max="300000" step="10000" value="180000" aria-label="${t.amount} max" data-extra="range-max">`;break;
 case 'avatar':h=`<div class="jy-row" style="gap:24px">${(v==='sizes'?[32,40,48,64,80]:[48,64,80]).map((n,i)=>`<span class="jy-avatar" style="--avatar-size:${n}px" role="img" aria-label="${x.profile}${v==='status'?', '+x.online:''}">${v==='image'?`<img src="./media/avatar.svg" alt="">`:`<span>${['JY',lang==='zh'?'游啦':'여라','A'][i%3]}</span>`}${v==='status'?`<span class="jy-avatar-status"></span>`:''}</span>`).join('')}</div><span class="jy-small jy-muted">${x.profile} · ${v==='image'?'Image':x.initial}</span>`;break;
 case 'tag':h=`<div class="jy-row">${[x.ocean,x.walk,x.nature].map((s,i)=>`<span class="jy-tag ${v==='outlined'?'outlined':''}">${v==='icon'?icon(['map','sun','mountain'][i],16):''}${s}</span>`).join('')}</div><p class="jy-small jy-muted">${t.description}</p>`;break;
 case 'radio-button':h=`<fieldset class="jy-radio-group"><legend class="jy-label">${x.region}</legend>${[t.east,t.west,t.south].map((s,i)=>`<label class="jy-radio-label"><input type="radio" name="travel-region" value="${s}" ${i===0?'checked':''} ${v==='disabled'?'disabled':''}><span><strong>${s}</strong>${v==='description'?`<small>${[t.seongsan,t.aewol,t.forest][i]}</small>`:''}</span></label>`).join('')}</fieldset>`;break;
 case 'chip':h=`<div class="jy-chip-group" data-single="${v==='single'}" role="group" aria-label="${x.filter}">${[x.ocean,x.walk,x.nature,x.cafe].map((s,i)=>v==='removable'?`<span class="jy-chip selected">${s}<button data-extra="chip-remove" class="jy-chip-remove" aria-label="${s} ${x.remove}">${icon('close',16)}</button></span>`:`<button class="jy-chip" aria-pressed="${i===0}" data-extra="chip" ${v==='disabled'?'disabled':''}>${i===0?icon('check',16):''}<span>${s}</span></button>`).join('')}</div><p class="jy-small jy-muted" data-chip-result>${x.ocean}</p>`;break;
 case 'pulldown':{const field='jy-region';h=`<div class="jy-field"><label class="jy-label" for="${field}">${x.region}</label><select id="${field}" class="jy-select ${v==='outlined'?'outlined':''}" data-extra="pulldown" ${v==='disabled'?'disabled':''} ${v==='error'?'aria-invalid="true" aria-describedby="jy-region-error"':''}><option value="" disabled selected>${x.choose}</option>${[t.east,t.west,t.south].map(s=>`<option>${s}</option>`).join('')}</select>${v==='error'?`<span class="jy-help jy-error" id="jy-region-error">${x.error}</span>`:''}<span class="jy-help" data-pulldown-result>${t.tip}</span></div>`;break;}
 case 'snackbar':h=`${Button(t.save,{display:'block',action:'extra-snackbar'})}<div class="jy-snackbar-preview"><span>${t.saved}</span>${v==='text'?'':`<button class="jy-snackbar-action" data-extra="undo-inline">${x.undo}</button>`}</div>`;break;
 case 'floating-action-button':h=`<div class="jy-fab-stage"><div class="jy-card"><strong>${t.trip}</strong><p class="jy-small jy-muted">${t.description}</p></div><div class="jy-fab-group"><div class="jy-fab-children" hidden>${[t.place,t.date].map((s,i)=>`<button class="jy-fab-child" data-extra="fab-child">${icon(i?'calendar':'pin',20)}${s}</button>`).join('')}</div><button class="jy-fab ${v==='extended'?'extended':''}" data-extra="fab" data-expand="${v==='expanded'}" aria-label="${t.step2}" ${v==='expanded'?'aria-expanded="false"':''}>${icon('plus',24)}${v==='extended'?`<span>${t.step2}</span>`:''}</button></div></div>`;break;
 case 'top-navigation':h=`<nav class="jy-topnav" aria-label="${t.explore}"><button class="jy-iconbtn" aria-label="${x.back}" data-extra="demo-action">${icon('back',24)}</button><h2>${v==='titleonly'?t.jeju:t.place}</h2>${v==='actions'?`<div class="jy-row"><button class="jy-iconbtn" aria-label="${t.search}" data-extra="demo-action">${icon('search',24)}</button><button class="jy-iconbtn" aria-label="${t.more}" data-extra="drawer">${icon('menu',24)}</button></div>`:`<button class="jy-iconbtn" aria-label="${t.save}" data-action="favorite" aria-pressed="false">${icon('heart',24)}</button>`}</nav><div class="jy-card"><p class="jy-body">${t.description}</p></div>`;break;
 case 'bottom-navigation':{let items=[['home',x.home],['map',x.explore],['heart',x.saved],['calendar',x.bookings],['user',x.my]];if(v==='threeitems')items=[items[0],items[1],items[4]];else if(v!=='fiveitems')items.splice(3,1);h=`<div class="jy-card"><strong data-nav-result>${x.home}</strong><p class="jy-small jy-muted">${t.description}</p></div><nav class="jy-bottomnav" aria-label="App navigation">${items.map(([ic,s],i)=>`<button data-extra="bottom-nav" ${i===0?'aria-current="page"':''}><span class="jy-navicon">${icon(ic,24)}${v==='notification'&&i===2?`<span class="jy-notification dot" aria-label="${t.new}"></span>`:''}</span><span>${s}</span></button>`).join('')}</nav>`;break;}
 case 'page-indicator':h=`<div class="jy-carousel" tabindex="0" aria-label="${t.explore}">${[t.seongsan,t.aewol,t.forest].map((s,i)=>`<figure class="jy-carousel-slide">${assetImg(i,`${s} · ${x.example}`)}<figcaption>${s}</figcaption></figure>`).join('')}</div><div class="jy-indicator-row">${v==='number'?'':`<div class="jy-dots" role="group" aria-label="${x.page}">${[0,1,2].map(i=>`<button class="jy-dot" data-extra="slide" data-index="${i}" aria-label="${x.page} ${i+1}" aria-current="${i===0?'true':'false'}"></button>`).join('')}</div>`}${v==='dots'?'':`<output class="jy-page-number" data-slide-number>1 / 3</output>`}</div>`;break;
 case 'page-controller':{const page=v==='last'?10:v==='first'?1:2;h=`<div class="jy-card" data-page-content>${t.place} · ${x.page} ${page}</div><nav class="jy-page-controller" data-current="${page}" data-total="10" aria-label="${x.page}"><button class="jy-iconbtn border" aria-label="${x.previous}" data-extra="page-prev" ${page===1?'disabled':''}>${icon('back',20)}</button><output aria-live="polite"><strong data-current-page>${page}</strong><span> / 10</span></output><button class="jy-iconbtn border" aria-label="${x.next}" data-extra="page-next" ${page===10?'disabled':''}>${icon('arrow',20)}</button></nav>`;break;}
 case 'image-grid':h=`<div class="jy-imagegrid ${v==='feature'?'feature':''}" style="--image-ratio:${v==='landscape'?'4/3':v==='portrait'?'3/4':'1/1'}">${[t.seongsan,t.aewol,t.forest,t.south].map((s,i)=>`<button class="jy-imageitem" data-extra="image-view">${assetImg(i,`${s} · ${x.example}`)}<span>${s}</span></button>`).join('')}</div>`;break;
 case 'video-player':h=`<div class="jy-video"><video playsinline preload="metadata" ${v==='muted'?'muted':''} aria-label="${x.video}"><source src="./media/flower.mp4" type="video/mp4"><track kind="captions" src="./media/captions-${lang}.vtt" srclang="${lang}" label="${lang.toUpperCase()}" default></video><div class="jy-video-controls"><div class="jy-row"><button class="jy-iconbtn" data-extra="video-play" aria-label="${x.play}">${icon('play',20)}</button><output data-video-time>0:00 / 0:00</output><button class="jy-iconbtn" data-extra="video-mute" aria-label="${v==='muted'?x.sound:x.mute}">${icon(v==='muted'?'muted':'volume',20)}</button></div><input class="jy-range" data-extra="video-seek" type="range" min="0" max="100" step=".1" value="0" aria-label="${x.seek}"><div class="jy-between"><button class="jy-iconbtn" data-extra="video-caption" aria-label="${x.captions}" aria-pressed="true">${icon('captions',20)}</button><button class="jy-iconbtn" data-extra="video-fullscreen" aria-label="${x.fullscreen}">${icon('maximize',20)}</button></div></div><p class="jy-help" data-video-error hidden>${x.videoError}</p></div><p class="jy-small jy-muted">${x.video} · MDN CC0</p>`;break;
 case 'side-drawer':h=`<div class="jy-card"><div class="jy-row"><span class="jy-avatar" style="--avatar-size:48px">JY</span><strong>${x.profile}</strong></div><p class="jy-small jy-muted">${t.description}</p></div><button class="jy-btn" data-extra="drawer" data-profile="${v==='profile'}">${icon('menu',20)}${x.drawer}</button>`;break;
 case 'footer':h=`<footer class="jy-appfooter" aria-label="${x.footer}"><strong>${t.brand}</strong><div class="jy-row">${[x.terms,x.privacy,x.support].map(s=>`<button class="jy-textbtn" data-extra="footer-info">${s}</button>`).join('')}</div><p>© Plander Designer ASEUL</p></footer>`;break;
 case 'expanded-tab-list':h=`<div class="jy-expanded-tabs"><div class="jy-expanded-top"><div class="jy-tabs" role="tablist" aria-label="${x.filter}">${[x.all,x.ocean,x.walk,x.nature,x.cafe].map((s,i)=>`<button role="tab" aria-selected="${i===0}" data-extra="expanded-select">${s}</button>`).join('')}</div><button class="jy-iconbtn" aria-label="${x.expand}" aria-expanded="${v==='expanded'}" data-extra="expand-tabs">${icon(v==='expanded'?'chevronup':'down',20)}</button></div><div class="jy-expanded-panel" ${v==='expanded'?'':'hidden'}>${[x.all,x.ocean,x.walk,x.nature,x.cafe,t.place,t.food,t.stay].map((s,i)=>`<button class="jy-chip" data-extra="expanded-choice" aria-pressed="${i===0}">${s}</button>`).join('')}</div><p class="jy-small jy-muted" data-expanded-result>${x.all}</p></div>`;break;
 default:throw new Error('Unknown component: '+id);
 }return h;
}
export function useSnackbar(message,{actionLabel='Undo',onAction,duration=6000}={}){document.querySelector('.jy-snackbar-live')?.remove();const trigger=document.activeElement;const box=document.createElement('div');box.className='jy-snackbar-live';box.innerHTML=`<span role="status">${esc(message)}</span><button class="jy-snackbar-action">${esc(actionLabel)}</button>`;document.body.append(box);let timer;const dismiss=()=>{const focused=box.contains(document.activeElement);box.remove();if(focused)trigger?.focus()};const start=()=>{clearTimeout(timer);timer=setTimeout(dismiss,duration)};box.addEventListener('focusin',()=>clearTimeout(timer));box.addEventListener('pointerenter',()=>clearTimeout(timer));box.addEventListener('focusout',start);box.addEventListener('pointerleave',start);box.querySelector('button').addEventListener('click',()=>{onAction?.();clearTimeout(timer);dismiss()});start();return {dismiss};}
export function openDrawer({lang='ko',profile=false}={}){const x=extraStrings[lang],t=strings[lang];const d=document.createElement('dialog');d.className='jy-overlay jy-drawer';d.lang=lang;d.setAttribute('aria-label',x.drawer);d.innerHTML=`<div class="jy-overlayinner"><div class="jy-between"><strong>${t.brand}</strong><button class="jy-iconbtn" data-drawer-close aria-label="${x.close}">${icon('close',24)}</button></div>${profile?`<div class="jy-row" style="padding:24px 0"><span class="jy-avatar" style="--avatar-size:48px">JY</span><strong>${x.profile}</strong></div>`:''}<nav>${[['home',x.home],['map',x.explore],['heart',x.saved],['user',x.my]].map(([ic,s])=>`<button class="jy-listrow" data-drawer-item>${icon(ic,24)}<span>${s}</span></button>`).join('')}</nav><p class="jy-small jy-muted" style="margin-top:32px">© Plander Designer ASEUL</p></div>`;document.body.append(d);d.addEventListener('click',e=>{const b=e.target.closest('[data-drawer-item]');if(b){d.close();useToast(b.textContent.trim())}if(e.target===d||e.target.closest('[data-drawer-close]'))d.close()});d.addEventListener('close',()=>d.remove(),{once:true});d.showModal();return{close:()=>d.close()};}
const time=n=>`${Math.floor((n||0)/60)}:${String(Math.floor((n||0)%60)).padStart(2,'0')}`;
export function mountExtraInteractions(root){
 root.addEventListener('click',async e=>{const b=e.target.closest('[data-extra]');const save=e.target.closest('[data-action="extra-snackbar"]');if(!b&&!save)return;const wrap=(b||save).closest('.jy-demo');if(!wrap)return;const lang=wrap.dataset.lang||'ko';const x=extraStrings[lang],t=strings[lang];if(save){useSnackbar(t.saved,{actionLabel:x.undo,onAction:()=>useToast(x.restored)});return}if(b.disabled)return;const a=b.dataset.extra;
 if(a==='chip'){const g=b.closest('.jy-chip-group');if(g.dataset.single==='true')g.querySelectorAll('button').forEach(c=>c.setAttribute('aria-pressed',c===b));else b.setAttribute('aria-pressed',b.getAttribute('aria-pressed')!=='true');wrap.querySelector('[data-chip-result]').textContent=[...g.querySelectorAll('[aria-pressed=true]')].map(c=>c.textContent.trim()).join(' · ')||x.all}
 if(a==='chip-remove'){b.parentElement.remove();wrap.querySelector('[data-chip-result]').textContent=[...wrap.querySelectorAll('.jy-chip')].map(c=>c.textContent.trim()).join(' · ')||x.all}
 if(a==='undo-inline'){b.disabled=true;b.closest('.jy-snackbar-preview').querySelector('span').textContent=x.restored;useToast(x.restored)}
 if(a==='fab'){if(b.dataset.expand==='true'){const g=b.parentElement.querySelector('.jy-fab-children');g.hidden=!g.hidden;b.setAttribute('aria-expanded',!g.hidden);b.innerHTML=icon(g.hidden?'plus':'close',24)}else useToast(t.step2)}
 if(a==='fab-child'||a==='demo-action')useToast(a==='fab-child'?b.textContent.trim():x.notice);
 if(a==='drawer')openDrawer({lang,profile:b.dataset.profile==='true'});
 if(a==='bottom-nav'){b.parentElement.querySelectorAll('button').forEach(c=>c.removeAttribute('aria-current'));b.setAttribute('aria-current','page');wrap.querySelector('[data-nav-result]').textContent=b.textContent.trim()}
 if(a==='slide'){const carousel=wrap.querySelector('.jy-carousel');carousel.scrollTo({left:Number(b.dataset.index)*carousel.clientWidth,behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'auto':'smooth'})}
 if(a==='page-prev'||a==='page-next'){const p=b.parentElement;const n=Math.max(1,Math.min(Number(p.dataset.total),Number(p.dataset.current)+(a==='page-next'?1:-1)));p.dataset.current=n;p.querySelector('[data-current-page]').textContent=n;p.querySelector('[data-extra=page-prev]').disabled=n===1;p.querySelector('[data-extra=page-next]').disabled=n===Number(p.dataset.total);wrap.querySelector('[data-page-content]').textContent=`${t.place} · ${x.page} ${n}`}
 if(a==='image-view'){const img=b.querySelector('img');const d=document.createElement('dialog');d.className='jy-overlay jy-image-viewer';d.setAttribute('aria-label',img.alt);d.innerHTML=`<button class="jy-iconbtn" aria-label="${x.close}">${icon('close',24)}</button><img src="${esc(img.getAttribute('src'))}" alt="${esc(img.alt)}"><p>${esc(img.alt)}</p>`;document.body.append(d);d.addEventListener('click',e=>{if(e.target===d||e.target.closest('button'))d.close()});d.addEventListener('close',()=>d.remove(),{once:true});d.showModal()}
 if(a.startsWith('video-')){const v=wrap.querySelector('video');if(a==='video-play'){if(v.paused){try{await v.play()}catch{useToast(x.videoError)}}else v.pause()}if(a==='video-mute'){v.muted=!v.muted;b.innerHTML=icon(v.muted?'muted':'volume',20);b.setAttribute('aria-label',v.muted?x.sound:x.mute)}if(a==='video-fullscreen'){try{await v.parentElement.requestFullscreen()}catch{useToast(x.notice)}}if(a==='video-caption'){const on=b.getAttribute('aria-pressed')!=='true';for(const track of v.textTracks)track.mode=on?'showing':'disabled';b.setAttribute('aria-pressed',on)}}
 if(a==='footer-info')useDialog({title:b.textContent.trim(),description:x.notice,confirmLabel:t.confirm,lang});
 if(a==='expand-tabs'){const panel=wrap.querySelector('.jy-expanded-panel');panel.hidden=!panel.hidden;b.setAttribute('aria-expanded',!panel.hidden);b.setAttribute('aria-label',panel.hidden?x.expand:x.collapse);b.innerHTML=icon(panel.hidden?'down':'chevronup',20)}
 if(a==='expanded-select'||a==='expanded-choice'){const value=b.textContent.trim();wrap.querySelectorAll('[data-extra=expanded-select]').forEach(c=>c.setAttribute('aria-selected',c.textContent.trim()===value));wrap.querySelectorAll('[data-extra=expanded-choice]').forEach(c=>c.setAttribute('aria-pressed',c.textContent.trim()===value));wrap.querySelector('[data-expanded-result]').textContent=value;if(a==='expanded-choice'){const panel=wrap.querySelector('.jy-expanded-panel');panel.hidden=true;const toggle=wrap.querySelector('[data-extra=expand-tabs]');toggle.setAttribute('aria-expanded','false');toggle.innerHTML=icon('down',20)}}
 });
 root.addEventListener('change',e=>{const el=e.target;if(el.dataset.extra==='pulldown'){el.closest('.jy-demo').querySelector('[data-pulldown-result]').textContent=el.value;el.removeAttribute('aria-invalid')}});
 root.addEventListener('input',e=>{if(['range-min','range-max'].includes(e.target.dataset.extra)){const wrap=e.target.closest('.jy-demo');const low=wrap.querySelector('[data-extra=range-min]'),high=wrap.querySelector('[data-extra=range-max]');if(Number(low.value)>Number(high.value)){if(e.target===low)low.value=high.value;else high.value=low.value}wrap.querySelector('[data-range-min-label]').textContent=Number(low.value).toLocaleString();wrap.querySelector('[data-range-max-label]').textContent=Number(high.value).toLocaleString()}if(e.target.dataset.extra==='video-seek'){const v=e.target.closest('.jy-video').querySelector('video');if(Number.isFinite(v.duration))v.currentTime=Number(e.target.value)}});
 root.addEventListener('scroll',e=>{if(!e.target.matches?.('.jy-carousel'))return;const c=e.target,wrap=c.closest('.jy-demo');const i=Math.round(c.scrollLeft/c.clientWidth);wrap.querySelectorAll('.jy-dot').forEach((d,n)=>d.setAttribute('aria-current',n===i?'true':'false'));const out=wrap.querySelector('[data-slide-number]');if(out)out.textContent=`${i+1} / 3`},true);
 for(const event of ['loadedmetadata','timeupdate','play','pause','ended','error'])root.addEventListener(event,e=>{const v=e.target;if(v.tagName!=='VIDEO'||!v.closest('.jy-video'))return;const wrap=v.closest('.jy-demo'),x=extraStrings[wrap.dataset.lang];const box=v.closest('.jy-video');if(event==='error'){box.querySelector('[data-video-error]').hidden=false;return}const out=box.querySelector('[data-video-time]');out.textContent=`${time(v.currentTime)} / ${time(v.duration)}`;const seek=box.querySelector('[data-extra=video-seek]');seek.max=Number.isFinite(v.duration)?v.duration:100;seek.value=v.currentTime;const play=box.querySelector('[data-extra=video-play]');play.innerHTML=icon(v.paused?'play':'pause',20);play.setAttribute('aria-label',v.paused?x.play:x.pause)},true);
}
